contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, address other, uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        uint256 otherBalanceBefore = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 callerBalanceBefore = c.balances(caller); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted ||
            (c.balances(caller) == 0 && c.balances(other) == otherBalanceBefore)
        );
    }

    receive() external payable {}
}

